const CD_KEY='tulasi-clinical-documentation-v1';
const cdToday=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const cdDateAdd=(s,n)=>{const [y,m,d]=s.split('-').map(Number),x=new Date(y,m-1,d,12);x.setDate(x.getDate()+n);return [x.getFullYear(),String(x.getMonth()+1).padStart(2,'0'),String(x.getDate()).padStart(2,'0')].join('-')};
const cdDateLabel=s=>s?new Date(+s.slice(0,4),+s.slice(5,7)-1,+s.slice(8,10),12).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Anytime';
function cdLoad(){try{const x=JSON.parse(localStorage.getItem(CD_KEY)||'null');if(x)return Object.assign({episodes:{},drafts:{},submissions:[],assignments:{},audit:[]},x)}catch(e){}const today=cdToday(),episodes={};(typeof PTS!=='undefined'?PTS:[]).forEach(p=>episodes[p.id]={admissionDate:cdDateAdd(today,-Math.max(0,(p.day||1)-1)),dischargeDate:p.dc?today:''});return {episodes,drafts:{},submissions:[],assignments:{},audit:[]}}
let CD_DATA=cdLoad(),CD_WORKKEY='',CD_EDITOR_HTML='',CD_ROUTE_ACTIVE=false;
function cdSave(){try{localStorage.setItem(CD_KEY,JSON.stringify(CD_DATA))}catch(e){toast('Could not save documentation in this browser')}}
function cdActor(){return (signer()||S.role)+' · '+({lead:'Psychiatry Lead',psychiatrist:'Psychiatrist',psychologist:'Psychologist',nurse:'Nurse',rmo:'RMO on duty'}[S.role]||S.role)}
function cdLog(pid,formId,action,detail){CD_DATA.audit.unshift({pid,formId,action,detail:detail||'',actor:cdActor(),at:new Date().toISOString()});CD_DATA.audit=CD_DATA.audit.slice(0,2000);cdSave()}
function cdAllowed(formId,role){const f=CD_FORMS.find(x=>x.id===formId);return !!f&&((CD_DATA.assignments[formId]||f.roles).includes(role))}
function cdItems(pid){const p=allPts().find(x=>x.id===pid);if(!p)return [];const ep=CD_DATA.episodes[pid]||{},ad=ep.admissionDate||cdDateAdd(cdToday(),-Math.max(0,(p.day||1)-1)),today=cdToday(),elapsed=Math.max(0,Math.floor((new Date(today+'T12:00:00')-new Date(ad+'T12:00:00'))/86400000)),out=[];
 const add=(f,occ,due,meta)=>{const entryKey=[pid,f.id,occ].join('|'),sub=CD_DATA.submissions.find(x=>x.entryKey===entryKey),status=sub?'Completed':!due?'Available':due<today?'Overdue':due===today?'Due':'Pending';out.push({form:f,occ,due,meta,entryKey,submission:sub,status})};
 CD_FORMS.forEach(f=>{if(f.schedule==='admission')add(f,'admission',ad,'At admission');else if(f.schedule==='window')add(f,'admission-window',ad,'During admission');else if(f.schedule==='capacity'){add(f,'admission',ad,'At admission');for(let d=7;d<=Math.min(elapsed,28);d+=7)add(f,'day-'+d,cdDateAdd(ad,d),'Week '+(d/7));if(elapsed>28)for(let d=42;d<=elapsed;d+=14)add(f,'day-'+d,cdDateAdd(ad,d),'Fortnightly · day '+d)}else if(f.schedule==='weekly'){for(let d=7;d<=elapsed;d+=7)add(f,'day-'+d,cdDateAdd(ad,d),'Week '+(d/7));if(elapsed<7)add(f,'day-7',cdDateAdd(ad,7),'Week 1')}else if(f.schedule==='72h')add(f,'72h',cdDateAdd(ad,3),'72-hour deadline');else if(f.schedule==='week')add(f,'week1',cdDateAdd(ad,7),'Week 1');else if(f.schedule==='daily'){for(let d=0;d<=elapsed;d++)add(f,'day-'+d,cdDateAdd(ad,d),d?'Day '+d:'Admission day')}else if(f.schedule==='therapy'){for(let d=3;d<=elapsed;d+=3)add(f,'day-'+d,cdDateAdd(ad,d),'Day '+d);if(elapsed<3)add(f,'day-3',cdDateAdd(ad,3),'First session')}else if(f.schedule==='discharge'){if(ep.dischargeDate)add(f,'discharge',ep.dischargeDate,'At discharge');else add(f,'discharge','',f.cadence)}else add(f,'available','',f.cadence)});
 const drafts=CD_DATA.drafts||{};out.forEach(x=>{if(!x.submission&&Object.prototype.hasOwnProperty.call(drafts,x.entryKey)&&x.status==='Available')x.status='Pending'});return out.sort((a,b)=>({Overdue:0,Due:1,Pending:2,Available:3,Completed:4}[a.status]-({Overdue:0,Due:1,Pending:2,Available:3,Completed:4}[b.status])||String(a.due).localeCompare(String(b.due))||a.form.title.localeCompare(b.form.title)))}
function cdPage(pane,entryKey){const dest='#/clinical-docs/'+pane+(entryKey?'/'+encodeURIComponent(entryKey):'');if(location.hash===dest)render();else location.hash=dest}
function cdOpen(pid){cdCapture();CD_DATA=cdLoad();S.cdPatient=pid||'kabir';S.cdTab='documents';S.cdFilter='all';S.cdQuery='';S.cdEntryKey='';S.cdFromRoute='';S.cdEditing=false;S.cdDirty=false;CD_WORKKEY='';CD_ROUTE_ACTIVE=true;cdPage('documents')}
function cdEsc(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function cdSelect(entryKey){cdCapture();S.cdFromRoute=location.hash||'#/clinical-docs/documents';S.cdEntryKey=entryKey;S.cdEditing=false;CD_WORKKEY='';cdPage('form',entryKey)}
function cdSetTab(t){cdCapture();S.cdTab=t;S.cdFromRoute='';cdPage(t)}
function cdFilter(f){cdCapture();S.cdFilter=f;render()}
function cdPatient(pid){cdCapture();S.cdPatient=pid;S.cdEntryKey='';S.cdFromRoute='';S.cdTab='documents';CD_WORKKEY='';cdPage('documents')}
function cdCapture(){const e=document.getElementById('cd-document-editor');if(e&&S.cdDirty&&S.cdEntryKey&&CD_WORKKEY===S.cdEntryKey){CD_EDITOR_HTML=e.innerHTML;CD_DATA.drafts[S.cdEntryKey]=CD_EDITOR_HTML;S.cdDirty=false;cdSave()}}
function cdAutofill(markup,p,ep){const root=document.createElement('div');root.innerHTML=markup||'';const today=cdDateLabel(cdToday()),adm=cdDateLabel(ep.admissionDate);const values={'name':p.name,'name of patient':p.name,'name of the patient':p.name,'patient name':p.name,'age':p.age,'sex':p.sex,'gender':p.sex,'uhid':p.uhid,'patient id':p.uhid,'patient id no':p.uhid,'patient id no.':p.uhid,'room':p.room,'diagnosis':p.dx,'provisional diagnosis':p.dx,'admission date':adm,'date of admission':adm,'date of assessment':today,'date':today};const norm=n=>(n.textContent||'').replace(/\u00a0/g,' ').replace(/\s+/g,' ').replace(/[：:]+$/g,'').trim().toLowerCase();root.querySelectorAll('tr').forEach(row=>{const cells=[...row.children].filter(c=>/^(TD|TH)$/i.test(c.tagName));cells.forEach((cell,i)=>{const val=values[norm(cell)],target=cells[i+1];if(!val||!target||target.querySelector('[data-cd-fill]')||(target.textContent||'').trim())return;const t=target.querySelector('p')||target;t.innerHTML='';const span=document.createElement('span');span.dataset.cdFill='true';span.textContent=val;t.appendChild(span)})});return root.innerHTML}
function cdStatusStyle(st){return {Pending:['#f9fafb','#475467','#d0d5dd'],Due:['#eff8ff','#175cd3','#84caff'],Overdue:['#fef3f2','#b42318','#fda29b'],Completed:['#ecfdf3','#067647','#abefc6'],Available:['#fffaeb','#b54708','#fedf89']}[st]||['#f9fafb','#475467','#d0d5dd']}
function cdButton(label,onclick,primary){return `<button class="btn sm ${primary?'pri':''}" onclick="${onclick}">${label}</button>`}
function vClinicalDocs(){
 $('title').textContent='Clinical documentation';CD_DATA=cdLoad();const route=(location.hash||'#/clinical-docs/documents').slice(2).split('/'),page=route[1]||'documents',formPage=page==='form';S.cdTab=['documents','history','audit','assignments'].includes(page)?page:'documents';let routeEntry='';if(formPage){try{routeEntry=decodeURIComponent(route[2]||'')}catch(e){}}const p=allPts().find(x=>x.id===(S.cdPatient||'kabir'))||allPts()[0];if(!p)return '<div class="card pad">No inpatient records found.</div>';S.cdPatient=p.id;
 const all=cdItems(p.id),selected=formPage?all.find(x=>x.entryKey===routeEntry):all.find(x=>x.entryKey===S.cdEntryKey)||all.find(x=>x.form.id==='admission-consent')||all[0];if(formPage&&!selected)return '<div class="card pad"><button class="btn sm" onclick="cdBack()">← Back to documents</button><p>This form is no longer available for this patient.</p></div>';if(selected)S.cdEntryKey=selected.entryKey;
 const counts={};['Pending','Due','Overdue','Completed','Available'].forEach(k=>counts[k]=all.filter(x=>x.status===k).length);const filter=S.cdFilter||'all',query=(S.cdQuery||'').toLowerCase();const visible=all.filter(x=>(filter==='all'||x.status.toLowerCase()===filter)&&(!query||(x.form.title+' '+x.meta+' '+x.status).toLowerCase().includes(query)));
 const selectedForm=selected&&selected.form,editable=selected&&cdAllowed(selected.form.id,S.role)&&(!selected.submission||S.cdEditing),storeEp=CD_DATA.episodes[p.id]||{},roles=['lead','psychiatrist','psychologist'];
 const tab=(key,label)=>`<button class="cd-tab ${S.cdTab===key?'on':''}" onclick="cdSetTab('${key}')">${label}${key==='history'?' · '+CD_DATA.submissions.filter(x=>x.pid===p.id).length:''}</button>`,tabsNav=`${tab('documents','Documents')}${tab('history','History')}${tab('audit','Audit')}${['lead'].includes(S.role)?tab('assignments','Assignments'):''}`,backTo=(S.cdFromRoute||'').includes('/history')?'History':'Documents';
 let side='';if(S.cdTab==='documents')side=`<div class="cd-metrics">${['Pending','Due','Overdue','Completed','Available'].map(k=>`<div class="cd-metric"><span class="tiny muted">${k}</span><b style="color:${cdStatusStyle(k)[1]}">${counts[k]}</b></div>`).join('')}</div><div class="cd-list-head"><input class="input" placeholder="Search forms" value="${cdEsc(S.cdQuery||'')}" oninput="S.cdQuery=this.value;cdCapture();const y=this.selectionStart;render();const q=document.querySelector('.cd-list-head input');q.focus();q.setSelectionRange(y,y)"><div class="cd-filters">${[['all','All',all.length],...['Pending','Due','Overdue','Completed','Available'].map(k=>[k.toLowerCase(),k,counts[k]])].map(([k,l,n])=>`<button class="tog ${filter===k?'on':''}" onclick="cdFilter('${k}')">${l} · ${n}</button>`).join('')}</div></div><div class="cd-list-scroll">${visible.map(x=>{const st=cdStatusStyle(x.status);return `<button class="cd-item ${x.entryKey===selected?.entryKey?'on':''}" style="border-left-color:${st[2]}" onclick="cdSelect('${cdEsc(x.entryKey)}')"><span class="row" style="justify-content:space-between;gap:6px"><b class="small">${cdEsc(x.form.title)} · ${cdEsc(x.meta)}</b><span class="chip" style="background:${st[0]};color:${st[1]}">${x.status}</span></span><span class="tiny muted">${x.due?'Due '+cdDateLabel(x.due):x.form.cadence}</span></button>`}).join('')||'<div class="cd-empty">No forms match this filter.</div>'}</div>`;
 else if(S.cdTab==='history'){const hist=CD_DATA.submissions.filter(x=>x.pid===p.id).slice().sort((a,b)=>(b.updatedAt||b.submittedAt).localeCompare(a.updatedAt||a.submittedAt));side=`<div class="cd-list-head"><b>Submitted documentation</b><span class="tiny muted">Patient-wise history, newest first</span></div><div class="cd-list-scroll">${hist.map(x=>`<button class="cd-item" onclick="cdOpenRecord('${cdEsc(x.entryKey)}')"><b class="small">${cdEsc((CD_FORMS.find(f=>f.id===x.formId)||{}).title||x.formId)}</b><span class="tiny muted">${cdEsc(x.author||'Unknown author')} · ${new Date(x.updatedAt||x.submittedAt).toLocaleString('en-IN')}</span></button>`).join('')||'<div class="cd-empty">No submitted forms for this stay.</div>'}</div>`}
 else if(S.cdTab==='audit'){side=`<div class="cd-list-head"><b>Audit log</b><span class="tiny muted">Opens, saves, submissions and assignment changes</span></div><div class="cd-list-scroll">${CD_DATA.audit.filter(x=>x.pid===p.id).slice(0,150).map(x=>`<div class="cd-audit-row"><b class="small">${cdEsc(x.action)} · ${cdEsc((CD_FORMS.find(f=>f.id===x.formId)||{}).title||'Patient stay')}</b><span class="tiny muted">${cdEsc(x.actor)} · ${new Date(x.at).toLocaleString('en-IN')}</span>${x.detail?`<span class="tiny">${cdEsc(x.detail)}</span>`:''}</div>`).join('')||'<div class="cd-empty">No audit events yet.</div>'}</div>`}
 else {side=`<div class="cd-list-head"><b>Form assignments</b><span class="tiny muted">Choose which roles can fill and publish each form.</span></div><div class="cd-list-scroll">${CD_FORMS.map(f=>`<div class="cd-item"><b class="small">${cdEsc(f.title)}</b><div class="cd-filters">${roles.map(r=>{const on=(CD_DATA.assignments[f.id]||f.roles).includes(r);return `<button class="tog ${on?'on':''}" onclick="cdToggleAssignment('${f.id}','${r}')">${({lead:'Psychiatry Lead',psychiatrist:'Psychiatrist',psychologist:'Psychologist'})[r]}</button>`}).join('')}</div></div>`).join('')}</div>`}
 let editor='';if(formPage&&selected){const src=CD_TEMPLATES[selected.form.template]||{html:'<div></div>',css:''};const sub=selected.submission;const html=sub?sub.html:(CD_DATA.drafts[selected.entryKey]||cdAutofill(src.html,p,storeEp));CD_EDITOR_HTML=html;editor=`<div class="cd-editor-head"><div class="cd-editor-title"><div style="flex:1;min-width:220px"><b>${cdEsc(selected.form.title)}</b><div class="tiny muted" style="margin-top:4px">${cdEsc(selected.due?cdDateLabel(selected.due):selected.form.cadence)} · Assigned to: ${selected.form.roles.map(r=>({lead:'Psychiatry Lead',psychiatrist:'Psychiatrist',psychologist:'Psychologist'})[r]).join(', ')}</div><div class="tiny muted">${sub?'Submitted '+new Date(sub.submittedAt).toLocaleString('en-IN')+' by '+cdEsc(sub.author):CD_DATA.drafts[selected.entryKey]?'Draft saved · '+cdEsc(cdActor()):'Template ready · patient details populated where matching fields are available'}</div></div><div class="cd-toolbar">${selected.form.id==='admission-consent'&&editable?`<button class="btn sm pri" onclick="cdAdmissionForm()">Fill details &amp; generate PDF</button>`:editable?`<button class="btn sm" onclick="cdFormat('bold')"><b>B</b></button><button class="btn sm" onclick="cdFormat('italic')"><i>I</i></button><button class="btn sm" onclick="cdFormat('underline')"><u>U</u></button><button class="btn sm" onclick="cdFormat('insertUnorderedList')">• List</button><button class="btn sm" onclick="cdFormat('undo')">↶</button><button class="btn sm" onclick="cdFormat('redo')">↷</button><button class="btn sm" onclick="cdSaveDraft()">Save draft</button><button class="btn sm pri" onclick="cdSubmit()">${sub?'Publish update':'Submit / Publish'}</button>`:sub&&cdAllowed(selected.form.id,S.role)?`<button class="btn sm" onclick="cdEditSubmitted()">Edit record</button>`:''}</div></div>${editable?(selected.form.id==='admission-consent'?'<div class="callout blue small">Enter the patient and consent details to create a filled, printable Admission Consent PDF.</div>':'<div class="callout blue small">Original page layout is preserved. Click the form to enter text. Save draft or Submit / Publish when ready.</div>'):''}</div><div class="cd-editor-scroll"><div id="cd-document-editor" class="cd-paper" contenteditable="${editable&&selected.form.id!=='admission-consent'?'true':'false'}" spellcheck="true" oninput="CD_EDITOR_HTML=this.innerHTML;S.cdDirty=true">${html}</div></div>`}
 return `<div class="cd-wrap"><header class="cd-head"><div class="cd-head-title"><b style="font-size:18px">Clinical documentation</b><span class="small muted">${cdEsc(p.name)} · UHID ${cdEsc(p.uhid)} · ${cdEsc(p.room)} · ${p.age}/${cdEsc(p.sex)} · Day ${p.day}</span></div><div class="cd-head-actions"><label class="small muted">Patient <select class="input" style="width:auto;min-width:190px;min-height:38px" onchange="cdPatient(this.value)">${allPts().map(q=>`<option value="${q.id}" ${q.id===p.id?'selected':''}>${cdEsc(q.name)} · ${cdEsc(q.room)}</option>`).join('')}</select></label><span class="tiny muted">Saved in this browser</span><button class="btn sm" onclick="go('#/existing/Dashboard')">Close</button></div></header>${formPage?`<div class="cd-body" style="grid-template-columns:minmax(0,1fr);min-height:0"><section class="cd-main"><div style="padding:10px 18px;border-bottom:1px solid #eaecf0"><button class="btn sm" onclick="cdBack()">← Back to ${backTo}</button></div>${editor}</section></div>`:page==='documents'?`<div class="cd-body"><aside class="cd-side"><nav class="cd-tabs" aria-label="Documentation sections">${tabsNav}</nav>${side}</aside><section class="cd-main"><div class="cd-empty"><span style="font-size:30px">▤</span><b>Choose a form</b><span>Select a document from the list. It will open on its own page while you work.</span></div></section></div>`:`<div class="cd-body" style="grid-template-columns:minmax(0,1fr);min-height:0"><section class="cd-main"><nav class="cd-tabs" aria-label="Documentation sections">${tabsNav}</nav>${side}</section></div>`}</div>`;
}
function cdAfterRender(){const e=document.getElementById('cd-document-editor');const prev=document.getElementById('cd-form-style');if(prev)prev.remove();if(!e)return;const item=cdItems(S.cdPatient||'kabir').find(x=>x.entryKey===S.cdEntryKey),src=item&&CD_TEMPLATES[item.form.template];if(src&&src.css){const st=document.createElement('style');st.id='cd-form-style';st.textContent=src.css;document.head.appendChild(st)}if(CD_WORKKEY!==S.cdEntryKey){CD_WORKKEY=S.cdEntryKey;cdLog(S.cdPatient,item&&item.form.id,'Opened form',item&&item.meta||'');}}
function cdFormat(cmd){const e=document.getElementById('cd-document-editor');if(!e)return;e.focus();document.execCommand(cmd,false,null);CD_EDITOR_HTML=e.innerHTML;S.cdDirty=true}
function cdSaveDraft(){const e=document.getElementById('cd-document-editor'),item=cdItems(S.cdPatient).find(x=>x.entryKey===S.cdEntryKey);if(!e||!item||!cdAllowed(item.form.id,S.role)){toast('This form is not assigned to your role');return}CD_DATA.drafts[item.entryKey]=e.innerHTML;S.cdDirty=false;cdSave();cdLog(S.cdPatient,item.form.id,'Draft saved',item.due?'Deadline '+cdDateLabel(item.due):'');toast(item.form.title+' draft saved');render()}
function cdSubmit(){const e=document.getElementById('cd-document-editor'),item=cdItems(S.cdPatient).find(x=>x.entryKey===S.cdEntryKey);if(!e||!item||!cdAllowed(item.form.id,S.role)){toast('This form is not assigned to your role');return}if(item.submission&&!S.cdEditing){toast('Use Edit record to publish an audited update');return}const now=new Date().toISOString(),old=item.submission;let rec;if(old){rec={...old,html:e.innerHTML,revisions:(old.revisions||[]).concat([{html:old.html,at:old.updatedAt||old.submittedAt,author:old.updatedBy||old.author}]),updatedAt:now,updatedBy:cdActor()};CD_DATA.submissions=CD_DATA.submissions.map(x=>x.entryKey===item.entryKey?rec:x)}else{rec={id:'doc-'+Date.now(),pid:S.cdPatient,formId:item.form.id,occurrenceId:item.occ,entryKey:item.entryKey,dueDate:item.due||'',html:e.innerHTML,submittedAt:now,updatedAt:now,authorRole:S.role,author:cdActor(),revisions:[]};CD_DATA.submissions.push(rec)}delete CD_DATA.drafts[item.entryKey];S.cdEditing=false;S.cdDirty=false;cdSave();cdLog(S.cdPatient,item.form.id,old?'Submitted record updated':'Form submitted',item.due?'Deadline '+cdDateLabel(item.due):'');toast(old?item.form.title+' update published.':item.form.title+' submitted.');render()}
function cdAdmissionForm(){
 const p=allPts().find(x=>x.id===S.cdPatient)||allPts()[0],now=new Date(),pad=n=>String(n).padStart(2,'0'),dt=now.getFullYear()+'-'+pad(now.getMonth()+1)+'-'+pad(now.getDate())+'T'+pad(now.getHours())+':'+pad(now.getMinutes());
 openModal(`<div class="mh"><h3>Admission consent details</h3><button class="x" aria-label="Close" onclick="closeModal()">×</button></div><div class="mb"><div class="grid2">
 <label class="field"><span class="lbl">Patient name</span><input class="input" id="cdPdfName" value="${cdEsc(p.name)}"></label>
 <label class="field"><span class="lbl">Age / sex</span><input class="input" id="cdPdfAgeSex" value="${cdEsc(p.age+'/'+p.sex)}"></label>
 <label class="field"><span class="lbl">Address</span><input class="input" id="cdPdfAddress" placeholder="Enter patient address"></label>
 <label class="field"><span class="lbl">IP / UHID</span><input class="input" id="cdPdfIp" value="${cdEsc(p.uhid)}"></label>
 <label class="field"><span class="lbl">Date and time</span><input class="input" id="cdPdfDate" type="datetime-local" value="${dt}"></label>
 <label class="field"><span class="lbl">Treating consultant</span><input class="input" id="cdPdfConsultant" value="${cdEsc(signer()||'')}"></label>
 <label class="field"><span class="lbl">Guardian name</span><input class="input" id="cdPdfGuardian" placeholder="Parent / spouse / guardian"></label>
 <label class="field"><span class="lbl">Relation</span><select class="input" id="cdPdfRelation"><option>Son of</option><option>Daughter of</option><option>Wife of</option><option>Husband of</option><option>Guardian of</option></select></label>
 <label class="field"><span class="lbl">Relative signing</span><input class="input" id="cdPdfSigner" placeholder="Name of patient or relative"></label>
 <label class="field"><span class="lbl">Relation to patient</span><input class="input" id="cdPdfSignerRelation" placeholder="e.g. Mother, spouse"></label>
 <label class="field"><span class="lbl">Witness name</span><input class="input" id="cdPdfWitness" placeholder="Witness"></label>
 <label class="field"><span class="lbl">Advance amount (₹)</span><input class="input" id="cdPdfAdvance" placeholder="Amount"></label>
 </div><div class="tiny muted" style="margin-top:10px">Patient details are prefilled where available. The generated page keeps signature lines blank for signing.</div></div><div class="mf"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="cdGenerateAdmissionPdf()">Generate filled PDF</button></div>`);
}
function cdAdmissionMarkup(d){
 const src=CD_TEMPLATES['admission-consent'],root=document.createElement('div');root.innerHTML=src.html||'';
 const big=[...root.querySelectorAll('img')].find(x=>Number(x.getAttribute('width'))>=600);
 if(big)big.outerHTML=`<table class="cd-filled-patient"><tr><td><b>Name</b><br>${cdEsc(d.name)}</td><td><b>Age / Sex</b><br>${cdEsc(d.ageSex)}</td></tr><tr><td><b>Address</b><br>${cdEsc(d.address)||' '}</td><td><b>IP / UHID</b><br>${cdEsc(d.ip)}</td></tr><tr><td><b>Date / Time</b><br>${cdEsc(d.date)}</td><td><b>Treating Consultant</b><br>${cdEsc(d.consultant)}</td></tr></table>`;
 const intro=[...root.querySelectorAll('p')].find(x=>/^I\s/.test((x.textContent||'').trim())&&/Aged/i.test(x.textContent||''));
 if(intro)intro.textContent=`I, ${d.name}, aged ${d.ageSex}, ${d.relation} ${d.guardian}`;
 const amount=[...root.querySelectorAll('p')].find(x=>(x.textContent||'').includes('Rs.')&&(x.textContent||'').includes('---'));
 if(amount)amount.textContent=(amount.textContent||'').replace(/-+/,' '+(d.advance?'₹ '+d.advance:'____________')+' ');
 const sig=[...root.querySelectorAll('p')].find(x=>(x.textContent||'').includes('Signature of the patient or relatives'));
 if(sig){const p=document.createElement('p');p.className=sig.className;p.textContent=`Name: ${d.signer||'________________'} · Relation: ${d.signerRelation||'________________'} · Date / Time: ${d.date}`;sig.after(p)}
 const wit=[...root.querySelectorAll('p')].find(x=>(x.textContent||'').trim().startsWith('Witness'));
 if(wit)wit.textContent=`Witness: ${d.witness||'________________'}  ·  Date: ${d.date}`;
 return root.innerHTML;
}
function cdGenerateAdmissionPdf(){
 const get=id=>(document.getElementById(id)?.value||'').trim(),item=cdItems(S.cdPatient).find(x=>x.entryKey===S.cdEntryKey);
 if(!item||!cdAllowed(item.form.id,S.role)){toast('This form is not assigned to your role');return}
 const d={name:get('cdPdfName'),ageSex:get('cdPdfAgeSex'),address:get('cdPdfAddress'),ip:get('cdPdfIp'),date:(()=>{const v=get('cdPdfDate');return v?new Date(v).toLocaleString('en-IN'):''})(),consultant:get('cdPdfConsultant'),guardian:get('cdPdfGuardian'),relation:get('cdPdfRelation'),signer:get('cdPdfSigner'),signerRelation:get('cdPdfSignerRelation'),witness:get('cdPdfWitness'),advance:get('cdPdfAdvance')};
 if(!d.name){toast('Enter the patient name');return}
 const html=cdAdmissionMarkup(d),src=CD_TEMPLATES['admission-consent'],w=window.open('','_blank');if(!w){toast('Allow pop-ups to generate the PDF');return}
 const printCss=`${src.css||''}\n@page{size:A4;margin:14mm 12mm}body{margin:0;background:#fff}.cd-paper{width:auto;min-height:0;margin:0;padding:0;box-shadow:none}.cd-filled-patient{width:100%;border-collapse:collapse;border:1px solid #222;font:10pt Arial,sans-serif;margin:3mm 0 5mm}.cd-filled-patient td{width:50%;height:15mm;border:1px solid #333;padding:2mm 3mm;vertical-align:top}.cd-filled-patient b{font-size:8pt;color:#555}.cd-filled-patient td{overflow-wrap:anywhere}@media screen{body{padding:18px;background:#eef1f5}.cd-paper{width:210mm;min-height:297mm;margin:auto;padding:14mm 12mm;background:white;box-shadow:0 2px 14px #0002}}`;
 w.document.open();w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Admission Consent · ${cdEsc(d.name)}</title><style>${printCss}</style></head><body><main class="cd-paper">${html}</main><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),350));<\/script></body></html>`);w.document.close();
 const now=new Date().toISOString(),old=item.submission,rec=old?{...old,html,updatedAt:now,updatedBy:cdActor(),revisions:(old.revisions||[]).concat([{html:old.html,at:old.updatedAt||old.submittedAt,author:old.updatedBy||old.author}])}:{id:'doc-'+Date.now(),pid:S.cdPatient,formId:item.form.id,occurrenceId:item.occ,entryKey:item.entryKey,dueDate:item.due||'',html,submittedAt:now,updatedAt:now,authorRole:S.role,author:cdActor(),revisions:[]};
 if(old)CD_DATA.submissions=CD_DATA.submissions.map(x=>x.entryKey===item.entryKey?rec:x);else CD_DATA.submissions.push(rec);delete CD_DATA.drafts[item.entryKey];S.cdEditing=false;S.cdDirty=false;cdSave();cdLog(S.cdPatient,item.form.id,old?'Generated updated PDF':'Generated filled PDF','Admission consent');closeModal();toast('Filled PDF opened · choose Save as PDF in the print dialog');render();
}
function cdEditSubmitted(){S.cdEditing=true;render()}
function cdOpenRecord(entryKey){cdCapture();const rec=CD_DATA.submissions.find(x=>x.entryKey===entryKey);if(!rec)return;S.cdFromRoute=location.hash||'#/clinical-docs/history';S.cdEntryKey=entryKey;S.cdTab='documents';S.cdEditing=false;CD_WORKKEY='';cdPage('form',entryKey)}
function cdBack(){cdCapture();const dest=String(S.cdFromRoute||'#/clinical-docs/documents');S.cdFromRoute='';if(location.hash===dest)render();else location.hash=dest}
function cdClose(){cdCapture();go('#/existing/Dashboard')}
function cdToggleAssignment(formId,role){cdCapture();if(S.role!=='lead'){toast('Only Psychiatry Lead can change assignments');return}const f=CD_FORMS.find(x=>x.id===formId),cur=(CD_DATA.assignments[formId]||f.roles).slice(),next=cur.includes(role)?cur.filter(x=>x!==role):cur.concat(role);CD_DATA.assignments[formId]=next;cdSave();cdLog(S.cdPatient,formId,'Form assignment changed',(next.includes(role)?'Assigned to ':'Removed from ')+role);render()}
const cdBaseRender=render;render=function(){const route=(location.hash||'').slice(2).split('/');if(route[0]!=='clinical-docs'){if(CD_ROUTE_ACTIVE)cdCapture();CD_ROUTE_ACTIVE=false;const old=document.getElementById('cd-form-style');if(old)old.remove();CD_WORKKEY='';return cdBaseRender.apply(this,arguments)}if(!CD_ROUTE_ACTIVE){S.cdPatient='kabir';S.cdTab='documents';S.cdFilter='all';S.cdQuery='';S.cdEntryKey='';S.cdFromRoute='';S.cdEditing=false;S.cdDirty=false;CD_WORKKEY='';CD_ROUTE_ACTIVE=true}if(!S.cdPatient)S.cdPatient='kabir';renderSide(route);$('app').classList.remove('compact');$('view').innerHTML=vClinicalDocs();cdAfterRender()};
if((location.hash||'').slice(2).split('/')[0]==='clinical-docs')render();

